```tsx
// CheckoutPage.tsx
import React, { useMemo, useState } from "react";
import { CartItem, DeliveryAddress, AddressErrors } from "./types";
import "./CheckoutPage.css";

interface CheckoutPageProps {
  items: CartItem[];
  onBackToCart: () => void;
  onPay: (address: DeliveryAddress) => void;
  isProcessing?: boolean;
}

const FREE_SHIPPING_THRESHOLD = 100;
const SHIPPING_COST = 6.99;

const EMPTY_ADDRESS: DeliveryAddress = {
  fullName: "",
  street: "",
  city: "",
  postalCode: "",
  country: "",
  phone: "",
};

function formatPrice(value: number): string {
  return `$${value.toFixed(2)}`;
}

function validateAddress(address: DeliveryAddress): AddressErrors {
  const errors: AddressErrors = {};

  if (!address.fullName.trim()) {
    errors.fullName = "Full name is required";
  }
  if (!address.street.trim()) {
    errors.street = "Street address is required";
  }
  if (!address.city.trim()) {
    errors.city = "City is required";
  }
  if (!address.postalCode.trim()) {
    errors.postalCode = "Postal code is required";
  } else if (!/^[a-zA-Z0-9\s-]{3,10}$/.test(address.postalCode.trim())) {
    errors.postalCode = "Enter a valid postal code";
  }
  if (!address.country.trim()) {
    errors.country = "Country is required";
  }
  if (!address.phone.trim()) {
    errors.phone = "Phone number is required";
  } else if (!/^[+\d][\d\s-]{6,}$/.test(address.phone.trim())) {
    errors.phone = "Enter a valid phone number";
  }

  return errors;
}

export default function CheckoutPage({
  items,
  onBackToCart,
  onPay,
  isProcessing = false,
}: CheckoutPageProps) {
  const [address, setAddress] = useState<DeliveryAddress>(EMPTY_ADDRESS);
  const [errors, setErrors] = useState<AddressErrors>({});
  const [touched, setTouched] = useState<Partial<Record<keyof DeliveryAddress, boolean>>>({});

  const subtotal = useMemo(
    () => items.reduce((sum, item) => sum + item.price * item.quantity, 0),
    [items]
  );
  const shipping = subtotal === 0 || subtotal >= FREE_SHIPPING_THRESHOLD ? 0 : SHIPPING_COST;
  const total = subtotal + shipping;

  const handleFieldChange = (field: keyof DeliveryAddress, value: string) => {
    setAddress((prev) => ({ ...prev, [field]: value }));
  };

  const handleFieldBlur = (field: keyof DeliveryAddress) => {
    setTouched((prev) => ({ ...prev, [field]: true }));
    setErrors(validateAddress(address));
  };

  const handlePay = (event: React.FormEvent) => {
    event.preventDefault();

    const validationErrors = validateAddress(address);
    setErrors(validationErrors);
    setTouched({
      fullName: true,
      street: true,
      city: true,
      postalCode: true,
      country: true,
      phone: true,
    });

    if (Object.keys(validationErrors).length === 0 && items.length > 0) {
      onPay(address);
    }
  };

  const renderField = (
    field: keyof DeliveryAddress,
    label: string,
    options?: { placeholder?: string; type?: string; autoComplete?: string }
  ) => {
    const hasError = Boolean(touched[field] && errors[field]);
    return (
      <div className="form-field">
        <label htmlFor={field} className="form-label">
          {label}
        </label>
        <input
          id={field}
          name={field}
          type={options?.type ?? "text"}
          className={`form-input ${hasError ? "form-input--error" : ""}`}
          placeholder={options?.placeholder}
          autoComplete={options?.autoComplete}
          value={address[field]}
          onChange={(e) => handleFieldChange(field, e.target.value)}
          onBlur={() => handleFieldBlur(field)}
          aria-invalid={hasError}
          aria-describedby={hasError ? `${field}-error` : undefined}
        />
        {hasError && (
          <span id={`${field}-error`} className="form-error">
            {errors[field]}
          </span>
        )}
      </div>
    );
  };

  const isCartEmpty = items.length === 0;

  return (
    <div className="checkout-page">
      <header className="checkout-header">
        <button type="button" className="back-link" onClick={onBackToCart}>
          <span aria-hidden="true">&larr;</span> Back to cart
        </button>
        <h1 className="checkout-title">Checkout</h1>
      </header>

      <div className="checkout-layout">
        <section className="checkout-section" aria-labelledby="order-summary-heading">
          <h2 id="order-summary-heading" className="section-heading">
            Order Summary
          </h2>

          {isCartEmpty ? (
            <p className="empty-cart-message">Your cart is empty.</p>
          ) : (
            <ul className="cart-item-list">
              {items.map((item) => (
                <li key={item.id} className="cart-item">
                  <div className="cart-item-image">
                    {item.imageUrl ? (
                      <img src={item.imageUrl} alt={item.name} />
                    ) : (
                      <div className="cart-item-image-placeholder" aria-hidden="true" />
                    )}
                  </div>
                  <div className="cart-item-details">
                    <span className="cart-item-name">{item.name}</span>
                    <span className="cart-item-quantity">Qty: {item.quantity}</span>
                  </div>
                  <span className="cart-item-price">
                    {formatPrice(item.price * item.quantity)}
                  </span>
                </li>
              ))}
            </ul>
          )}

          <div className="order-totals">
            <div className="order-totals-row">
              <span>Subtotal</span>
              <span>{formatPrice(subtotal)}</span>
            </div>
            <div className="order-totals-row">
              <span>Shipping</span>
              <span>{shipping === 0 ? "Free" : formatPrice(shipping)}</span>
            </div>
            <div className="order-totals-row order-totals-row--total">
              <span>Total</span>
              <span>{formatPrice(total)}</span>
            </div>
          </div>
        </section>

        <section className="checkout-section" aria-labelledby="delivery-address-heading">
          <h2 id="delivery-address-heading" className="section-heading">
            Delivery Address
          </h2>

          <form className="address-form" onSubmit={handlePay} noValidate>
            {renderField("fullName", "Full name", {
              placeholder: "Jane Doe",
              autoComplete: "name",
            })}
            {renderField("street", "Street address", {
              placeholder: "123 Main St, Apt 4",
              autoComplete: "street-address",
            })}
            <div className="form-row">
              {renderField("city", "City", {
                placeholder: "Springfield",
                autoComplete: "address-level2",
              })}
              {renderField("postalCode", "Postal code", {
                placeholder: "12345",
                autoComplete: "postal-code",
              })}
            </div>
            <div className="form-row">
              {renderField("country", "Country", {
                placeholder: "United States",
                autoComplete: "country-name",
              })}
              {renderField("phone", "Phone number", {
                placeholder: "+1 555 123 4567",
                type: "tel",
                autoComplete: "tel",
              })}
            </div>

            <div className="checkout-actions">
              <button
                type="button"
                className="btn btn--secondary"
                onClick={onBackToCart}
                disabled={isProcessing}
              >
                Back to cart
              </button>
              <button
                type="submit"
                className="btn btn--primary"
                disabled={isCartEmpty || isProcessing}
              >
                {isProcessing ? "Processing..." : `Pay ${formatPrice(total)}`}
              </button>
            </div>
          </form>
        </section>
      </div>
    </div>
  );
}
```

