Example usage:

```tsx
// App.tsx
import React, { useState } from "react";
import CheckoutPage from "./CheckoutPage";
import { CartItem, DeliveryAddress } from "./types";

const sampleItems: CartItem[] = [
  { id: "1", name: "Wireless Headphones", price: 79.99, quantity: 1 },
  { id: "2", name: "USB-C Cable (2m)", price: 12.5, quantity: 2 },
];

export default function App() {
  const [isProcessing, setIsProcessing] = useState(false);

  const handlePay = (address: DeliveryAddress) => {
    setIsProcessing(true);
    console.log("Paying, deliver to:", address);
    setTimeout(() => setIsProcessing(false), 1500);
  };

  return (
    <CheckoutPage
      items={sampleItems}
      onBackToCart={() => console.log("navigate back to cart")}
      onPay={handlePay}
      isProcessing={isProcessing}
    />
  );
}
```

Notes:
- `CheckoutPage` is presentational/controlled: cart items and the back/pay handlers are passed in as props, so it plugs into whatever routing/state (React Router, Redux, context, etc.) you're already using.
- Validation runs on blur and on submit; `Pay` is disabled while `isProcessing` or when the cart is empty.
- Free shipping kicks in above `FREE_SHIPPING_THRESHOLD` — adjust the constants at the top of `CheckoutPage.tsx` to match your store's rules.
